create extension if not exists pgcrypto;
create type public.member_role as enum ('member','admin','founder');
create type public.request_status as enum ('pending','accepted','declined','cancelled');
create table public.members (id uuid primary key references auth.users(id) on delete cascade,role public.member_role not null default 'member',display_name text not null default '',photo_url text,bio text,interests text[] not null default '{}',languages text[] not null default '{}',city text,country text,eligibility_status text not null default 'pending',onboarding_completed boolean not null default false,onboarding_updated_at timestamptz not null default now(),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint completed_profile_requires_photo check(not onboarding_completed or photo_url is not null));
create table public.member_private (id uuid primary key references public.members(id) on delete cascade,email text not null unique,date_of_birth date,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.pal_requests (id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.members(id) on delete cascade,receiver_id uuid not null references public.members(id) on delete cascade,message text not null default '',experience_id uuid,status public.request_status not null default 'pending',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint pal_request_not_self check(sender_id<>receiver_id));
create unique index pal_requests_one_pending_direction on public.pal_requests(sender_id,receiver_id) where status='pending';
create table public.pal_connections (member_id uuid not null references public.members(id) on delete cascade,pal_id uuid not null references public.members(id) on delete cascade,connected_at timestamptz not null default now(),last_activity_at timestamptz not null default now(),primary key(member_id,pal_id),constraint pal_connection_not_self check(member_id<>pal_id));
create table public.private_conversations (id uuid primary key default gen_random_uuid(),member_a_id uuid not null references public.members(id) on delete cascade,member_b_id uuid not null references public.members(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint private_conversation_not_self check(member_a_id<member_b_id));
create unique index private_conversations_pair on public.private_conversations(member_a_id,member_b_id);
create table public.private_messages (id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.private_conversations(id) on delete cascade,sender_id uuid not null references public.members(id) on delete cascade,body text not null default '',message_type text not null default 'text',created_at timestamptz not null default now(),read_at timestamptz);
alter table public.members enable row level security; alter table public.member_private enable row level security; alter table public.pal_requests enable row level security; alter table public.pal_connections enable row level security; alter table public.private_conversations enable row level security; alter table public.private_messages enable row level security;
create policy "members read completed profiles or their own" on public.members for select using(onboarding_completed or auth.uid()=id);
create policy "members read only their private account data" on public.member_private for select using(auth.uid()=id);
create policy "members read own requests" on public.pal_requests for select using(auth.uid()=sender_id or auth.uid()=receiver_id);
create policy "members read own connections" on public.pal_connections for select using(auth.uid()=member_id or auth.uid()=pal_id);
create policy "members read own conversations" on public.private_conversations for select using(auth.uid()=member_a_id or auth.uid()=member_b_id);
create policy "members read own messages" on public.private_messages for select using(exists(select 1 from public.private_conversations c where c.id=conversation_id and(auth.uid()=c.member_a_id or auth.uid()=c.member_b_id)));
